#!/usr/bin/env python3
"""Regenerate lot3_fixtures.rs from verification/fixtures/lot3_clutter.json."""
from __future__ import annotations

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
JSON_PATH = ROOT / "verification" / "fixtures" / "lot3_clutter.json"
OUT = ROOT / "crates" / "stonesoup-scenarios" / "src" / "lot3_fixtures.rs"
MAX_DETS = 10


def main() -> None:
    data = json.loads(JSON_PATH.read_text(encoding="utf-8"))
    n = len(data["measurement_sets"])
    lines = [
        "// @generated by tools/python/lot3_fixtures_to_rust.py — do not edit",
        f"pub const NUM_STEPS: usize = {n};",
        f"pub const MAX_DETS_PER_STEP: usize = {MAX_DETS};",
    ]

    lines.append(f"pub const TRUTH: [[f64; 4]; NUM_STEPS] = [")
    for row in data["truth"]:
        lines.append(f"    {row},")
    lines.append("];")

    lines.append(f"pub const TRACK_REF: [[f64; 4]; NUM_STEPS] = [")
    for row in data["track"]:
        lines.append(f"    {row},")
    lines.append("];")

    counts = []
    flat_xy = []
    flat_true = []
    for step in data["measurement_sets"]:
        ms = step["measurements"]
        if len(ms) > MAX_DETS:
            raise SystemExit(f"step {step['step']}: {len(ms)} dets > MAX_DETS")
        counts.append(len(ms))
        for m in ms:
            flat_xy.append(m["xy"])
            flat_true.append(1 if m["kind"] == "true" else 0)

    lines.append(f"pub const MEAS_XY: [[f64; 2]; {len(flat_xy)}] = [")
    for row in flat_xy:
        lines.append(f"    {row},")
    lines.append("];")
    lines.append(f"pub const MEAS_IS_TRUE: [u8; {len(flat_true)}] = {flat_true};")

    # Prefix sums for step indexing into MEAS_XY.
    offsets = [0]
    for c in counts:
        offsets.append(offsets[-1] + c)
    lines.append(f"pub const MEAS_OFFSETS: [usize; NUM_STEPS + 1] = {offsets};")

    OUT.write_text("\n".join(lines) + "\n", encoding="utf-8")
    print("wrote", OUT)


if __name__ == "__main__":
    main()
